import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late Future<List<NewsModel>> _newsListFuture;

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  Future<List<NewsModel>> _loadNews({required bool refresh}) async {
    final newsRepository = context.read<NewsRepository>();
    return newsRepository.loadNewsFeed(NewsFeedFilter(forceRefresh: refresh));
  }

  void _initData() {
    _newsListFuture = _loadNews(refresh: true).then((List<NewsModel> value) {
      _scaleController.forward();
      return value;
    });
  }

  void _refreshNews() {
    setState(() {
      _newsListFuture = _loadNews(refresh: true);
      _scaleController.forward();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(context.loc.news),
        actions: [
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: context.loc.refresh,
            onPressed: _refreshNews,
          ),
        ],
      ),
      body: FutureBuilder<List<NewsModel>>(
        future: _newsListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> snapshot) {
          final List<NewsModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return ScaleTransition(
            scale: _scaleAnimation,
            child: ListView.builder(
              itemCount: data.length,
              itemBuilder: (_, i) {
                final NewsModel news = data[i];

                return Padding(
                  key: ValueKey(news.link),
                  padding: i == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
                  child: NewsCard(model: news),
                );
              },
              padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            ),
          );
        },
      ),
    );
  }
}
